import{_ as e,a as s,b as a,c as o,d as n,e as r,f as i,g as l,h as d,i as p}from"./chunks/10-settings.Ch5Rn4da.js";import{c as h,Q as c,j as g,m as u}from"./chunks/framework.t4rEqR7d.js";const S=JSON.parse('{"title":"Desktop: Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"desktop.md","filePath":"desktop.md"}'),m={name:"desktop.md"};function k(b,t,f,y,w,v){return c(),g("div",null,[...t[0]||(t[0]=[u('<h1 id="desktop-getting-started" tabindex="-1">Desktop: Getting Started <a class="header-anchor" href="#desktop-getting-started" aria-label="Permalink to &quot;Desktop: Getting Started&quot;">​</a></h1><p>Language: <a href="/pagent/zh/desktop.html">中文</a> | English</p><p><strong>pagent Desktop</strong> is a desktop app that lets you chat with an AI and have it do real work on your computer. You describe a task in plain language; it reads and writes files, runs commands, and generates web pages or PDFs — with the results shown on the right side of the window.</p><p>This guide is for <strong>first-time users</strong>: from download to your first message, step by step. To work on the desktop source, see the <a href="https://github.com/SyncLionPaw/pagent/blob/main/editors/desktop/README.md" target="_blank" rel="noreferrer">developer README</a>.</p><div class="info custom-block"><p class="custom-block-title">The app UI is in Chinese</p><p>The desktop app currently ships <strong>Chinese-only</strong> UI. This guide keeps the on-screen Chinese labels in quotes (e.g. <strong>新建任务</strong> / New task) so you can match them to the buttons you actually see.</p></div><p><img src="'+e+'" alt="pagent Desktop main window: sessions on the left, chat in the center, files and artifacts on the right"></p><div class="tip custom-block"><p class="custom-block-title">Five-minute path</p><ol><li><a href="#step-1-install-the-backend-required">Install the <code>pagent</code> backend</a> →</li><li><a href="#step-2-download-the-app">Download and open the app</a> →</li><li><a href="#step-3-follow-the-setup-wizard">Follow the setup wizard for your API key</a> →</li><li><a href="#step-4-create-a-task-and-send-your-first-message">Create a task, send your first message</a></li></ol></div><hr><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A <strong>Mac (Apple Silicon, M1 or later)</strong>. For Windows / Linux, see <a href="#windows-linux">Other systems</a>.</li><li>An <strong>API key</strong> from a model provider (e.g. DeepSeek&#39;s <code>sk-...</code>). No key yet? The wizard points you to where to get one.</li><li>About 10 minutes.</li></ul><p>No coding required, and you don&#39;t need Docker up front.</p><hr><h2 id="step-1-install-the-backend-required" tabindex="-1">Step 1: Install the backend (required) <a class="header-anchor" href="#step-1-install-the-backend-required" aria-label="Permalink to &quot;Step 1: Install the backend (required)&quot;">​</a></h2><p>The desktop app is just the shell. The real work is done by a command-line program called <code>pagent</code>. Install it first.</p><p>Open <strong>Terminal</strong> (search &quot;Terminal&quot; in Launchpad) and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pagent</span></span></code></pre></div><p><strong>No <code>uv</code>?</strong> <code>uv</code> is a small tool for managing Python environments. Install it first via the <a href="./guide/install.html">install guide</a>, then come back and run the command above.</p><p>When <code>pagent --help</code> prints help text, you&#39;re good.</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t skip this</p><p>The app looks for the <code>pagent</code> command at startup. Without it, you&#39;ll see &quot;cannot start backend.&quot;</p></div><hr><h2 id="step-2-download-the-app" tabindex="-1">Step 2: Download the app <a class="header-anchor" href="#step-2-download-the-app" aria-label="Permalink to &quot;Step 2: Download the app&quot;">​</a></h2><p>Go to <a href="https://github.com/SyncLionPaw/pagent/releases" target="_blank" rel="noreferrer">pagent GitHub Releases</a> and download the latest:</p><ul><li><strong>macOS (Apple Silicon)</strong> — named like <code>pagent-Desktop-&lt;version&gt;-mac-arm64.zip</code></li></ul><p><strong>Unzip</strong> it and drag <strong>pagent Desktop</strong> into your <strong>Applications</strong> folder.</p><h3 id="macos-says-the-app-is-damaged" tabindex="-1">macOS says the app is &quot;damaged&quot;? <a class="header-anchor" href="#macos-says-the-app-is-damaged" aria-label="Permalink to &quot;macOS says the app is &quot;damaged&quot;?&quot;">​</a></h3><p><img src="'+s+'" alt="macOS dialog: pagent Desktop is damaged and can&#39;t be opened"></p><p>The app is <strong>not</strong> broken. Because it isn&#39;t signed with a paid Apple certificate, macOS blocks all &quot;unidentified&quot; apps this way. The fix is one line.</p><p>Open <strong>Terminal</strong> and run (adjust the path to where you installed it):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/pagent Desktop.app&quot;</span></span></code></pre></div><p>Then open the app normally. The unzipped folder also contains <strong><code>打开说明.txt</code></strong> (open instructions).</p><details class="details custom-block"><summary>Why does this happen?</summary><p><code>xattr -cr</code> removes the &quot;quarantine&quot; flag macOS puts on downloaded files. This is standard for unsigned apps — many open-source tools need the same step. Right-click → <strong>Open</strong> sometimes works too, but often not for the &quot;damaged&quot; message, so prefer the command above.</p></details><h3 id="windows-linux" tabindex="-1">Windows / Linux <a class="header-anchor" href="#windows-linux" aria-label="Permalink to &quot;Windows / Linux&quot;">​</a></h3><p>macOS is the main published build for now. Windows / Linux packages are being rolled out through CI. Until then, you can:</p><ul><li>Use the <a href="./vscode.html">VS Code extension</a> (cross-platform, same features), or</li><li>Use the <code>pagent</code> command line directly.</li></ul><hr><h2 id="step-3-follow-the-setup-wizard" tabindex="-1">Step 3: Follow the setup wizard <a class="header-anchor" href="#step-3-follow-the-setup-wizard" aria-label="Permalink to &quot;Step 3: Follow the setup wizard&quot;">​</a></h2><p>The <strong>first time</strong> you open the app, if <code>pagent</code> isn&#39;t installed or no API key is set, a setup wizard (<strong>首次设置</strong> / Setup) opens automatically. It has three steps and the main UI stays locked until you finish — just follow along.</p><p>The top reads <strong>完成下列步骤后即可开始使用。</strong> (Complete the steps below to get started.)</p><h3 id="step-1-—-environment-环境" tabindex="-1">Step 1 — Environment (<strong>环境</strong>) <a class="header-anchor" href="#step-1-—-environment-环境" aria-label="Permalink to &quot;Step 1 — Environment (**环境**)&quot;">​</a></h3><p><img src="'+a+'" alt="Setup wizard step 1: checking uv and pagent CLI"></p><p>This checks whether <code>uv</code> and the <code>pagent CLI</code> are installed:</p><ul><li>Both show <strong>已安装</strong> (Installed) → you&#39;ll see <strong>环境已就绪，可以继续。</strong> (Environment ready). Click <strong>下一步</strong> (Next).</li><li>Anything showing <strong>需要安装</strong> (Needs install) → click <strong>安装 pagent</strong> (Install pagent — the app does it for you), or <strong>复制命令</strong> (Copy command) to run it yourself, then <strong>重新检测</strong> (Re-check).</li></ul><h3 id="step-2-—-api-key" tabindex="-1">Step 2 — API Key <a class="header-anchor" href="#step-2-—-api-key" aria-label="Permalink to &quot;Step 2 — API Key&quot;">​</a></h3><p><img src="'+o+'" alt="Setup wizard step 2: enter API key, model, base URL"></p><p>Enter your model <strong>API Key</strong> (looks like <code>sk-...</code>) and pick a <strong>模型</strong> (Model). Leave <strong>Base URL（可选）</strong> (optional) empty to use the default.</p><ul><li>If a key is <strong>already detected</strong>, the wizard says so — fill it in only to change it.</li><li>The key is written to your local config file at <code>~/.pagent/pagent.toml</code>.</li></ul><h3 id="step-3-—-sandbox-沙箱" tabindex="-1">Step 3 — Sandbox (<strong>沙箱</strong>) <a class="header-anchor" href="#step-3-—-sandbox-沙箱" aria-label="Permalink to &quot;Step 3 — Sandbox (**沙箱**)&quot;">​</a></h3><p><img src="'+n+'" alt="Setup wizard step 3: choose sandbox — local / container / remote"></p><p>The &quot;sandbox&quot; is where the AI does its work. Pick <strong>本机</strong> (Local — recommended, no Docker); you can change it later per task. Click <strong>完成</strong> (Finish) to enter the app.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it means</th><th>For whom</th></tr></thead><tbody><tr><td><strong>本机</strong> (Local)</td><td>Runs directly on your Mac, no Docker</td><td>Almost everyone (default)</td></tr><tr><td><strong>容器</strong> (Container)</td><td>Runs inside a Docker/Podman container, more isolated</td><td>Need isolation, have Docker</td></tr><tr><td><strong>远程</strong> (Remote)</td><td>Runs on another machine over SSH</td><td>Advanced users</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Want to configure later?</p><p>The wizard has <strong>稍后配置</strong> (Set up later) at the bottom to skip some steps. But you <strong>must have an API key before sending a message</strong>, or you&#39;ll get an error.</p></div><p>You can reopen this wizard anytime from the bottom-left user menu → <strong>首次设置</strong> (Setup).</p><hr><h2 id="step-4-create-a-task-and-send-your-first-message" tabindex="-1">Step 4: Create a task and send your first message <a class="header-anchor" href="#step-4-create-a-task-and-send-your-first-message" aria-label="Permalink to &quot;Step 4: Create a task and send your first message&quot;">​</a></h2><p>In the main window, click <strong>新建任务</strong> (New task) on the left.</p><p><img src="'+r+'" alt="New task dialog: sandbox type, image, project folder"></p><p>Fill in three things:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to pick</th></tr></thead><tbody><tr><td><strong>沙箱类型</strong> (Sandbox)</td><td>Pick <strong>本机</strong> (Local — default, no Docker)</td></tr><tr><td><strong>镜像</strong> (Image)</td><td>Only appears for <strong>容器</strong> (Container); a local pagent image like <code>pagent:latest</code></td></tr><tr><td><strong>项目目录</strong> (Project folder)</td><td>Click <strong>浏览</strong> (Browse) and pick a folder — the AI reads/writes files here</td></tr></tbody></table><p>Click <strong>创建会话</strong> (Create session), type in the box at the bottom, and press <strong>Enter</strong> to send (<strong>Shift+Enter</strong> for a new line).</p><p>Try saying:</p><blockquote><p>Create an index.html in this folder — a simple personal homepage</p></blockquote><p>You&#39;ll watch the AI work step by step, and the generated page appears on the right.</p><hr><h2 id="get-to-know-the-main-window" tabindex="-1">Get to know the main window <a class="header-anchor" href="#get-to-know-the-main-window" aria-label="Permalink to &quot;Get to know the main window&quot;">​</a></h2><p><img src="'+e+'" alt="Three panes: sessions, chat, files and artifacts"></p><p>The window has three panes:</p><ul><li><strong>Left · Sessions</strong> — every conversation is saved here; click one to continue. <strong>新建任务</strong> (New task) is at the top.</li><li><strong>Center · Chat</strong> — messages, the AI&#39;s steps, and the composer.</li><li><strong>Right · Files &amp; artifacts</strong> — sandbox tree, project files, previews of generated pages/PDFs, and the run log.</li></ul><p>Drag the dividers to resize. Press <strong>⌘K</strong> or the shortcuts button in the title bar to see all shortcuts.</p><h3 id="the-composer" tabindex="-1">The composer <a class="header-anchor" href="#the-composer" aria-label="Permalink to &quot;The composer&quot;">​</a></h3><p><img src="'+i+'" alt="Composer: send, YOLO lightning, ring, @ mention"></p><p>The placeholder reads <strong>给 pagent 下达任务，输入 @ 引用文件</strong> (Give pagent a task, type @ to reference a file). Key controls:</p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Send / Stop</strong> (发送 / 停止)</td><td>Send a message; becomes <strong>停止</strong> (Stop) while the AI runs, to cancel</td></tr><tr><td><strong>Lightning (YOLO)</strong></td><td>When on, tool calls are <strong>auto-approved</strong> — turn on only when you trust the task</td></tr><tr><td><strong>Ring</strong></td><td>Rough share of context used in this conversation</td></tr><tr><td><strong>@</strong></td><td>Type <code>@</code> to reference a file from your project or sandbox</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">About YOLO (lightning)</p><p>By default the AI <strong>asks for approval</strong> before touching files or running commands. YOLO turns that off and <strong>auto-approves everything</strong> — fast but risky. Only enable it when you&#39;re sure the task is safe.</p></div><h3 id="right-side-files-artifacts" tabindex="-1">Right side: files &amp; artifacts <a class="header-anchor" href="#right-side-files-artifacts" aria-label="Permalink to &quot;Right side: files &amp; artifacts&quot;">​</a></h3><p><img src="'+l+'" alt="Right panel: file tree, artifact preview, log"></p><p>Generated pages, PDFs, and images preview right here. The file tree shows everything in the sandbox and project, and the log shows what the backend is doing — <strong>check here first when something goes wrong</strong>.</p><hr><h2 id="everyday-tasks" tabindex="-1">Everyday tasks <a class="header-anchor" href="#everyday-tasks" aria-label="Permalink to &quot;Everyday tasks&quot;">​</a></h2><h3 id="delete-a-session" tabindex="-1">Delete a session <a class="header-anchor" href="#delete-a-session" aria-label="Permalink to &quot;Delete a session&quot;">​</a></h3><p>In the session list, hover a session and click the <strong>删除会话</strong> (Delete session) icon. A confirmation appears:</p><p><img src="'+d+'" alt="Delete session confirmation dialog"></p><p>It reads <strong>删除「session title」后无法恢复，确认删除吗？</strong> (Deleting &quot;…&quot; can&#39;t be undone — delete it?). Click <strong>删除</strong> (Delete) to confirm, or <strong>取消</strong> (Cancel). <strong>This can&#39;t be undone</strong>, so double-check first.</p><h3 id="switch-resume-sessions" tabindex="-1">Switch / resume sessions <a class="header-anchor" href="#switch-resume-sessions" aria-label="Permalink to &quot;Switch / resume sessions&quot;">​</a></h3><p>Click any session on the left to switch to it. On startup, the app tries to <strong>resume your most recent session</strong> automatically.</p><hr><h2 id="settings-help" tabindex="-1">Settings &amp; help <a class="header-anchor" href="#settings-help" aria-label="Permalink to &quot;Settings &amp; help&quot;">​</a></h2><p><img src="'+p+`" alt="Settings panel: environment health lights + disk usage"></p><table tabindex="0"><thead><tr><th>Entry</th><th>What&#39;s inside</th></tr></thead><tbody><tr><td>Title bar <strong>Gear</strong> (设置 / Settings)</td><td><strong>环境自检</strong> (Environment health — status lights for uv / pagent / API key / container) + <strong>磁盘占用</strong> (Disk usage) + view <code>pagent.toml</code></td></tr><tr><td>Title bar <strong>Book</strong> (文档 / Docs)</td><td>Open this documentation site in the browser</td></tr><tr><td>User menu <strong>扫码看文档</strong> (Scan for docs)</td><td>QR code to read the docs on your phone</td></tr><tr><td>User menu <strong>首次设置</strong> (Setup)</td><td>Reopen the three-step setup wizard</td></tr></tbody></table><p>The config shown in Settings is <strong>read-only</strong>. To change the model or advanced options, edit <code>~/.pagent/pagent.toml</code> in a text editor.</p><details class="details custom-block"><summary>Prefer to configure the key manually?</summary><p><strong>Option 1 · Environment variable:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span></code></pre></div><p><strong>Option 2 · Config file (recommended):</strong> create <code>~/.pagent/pagent.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4-flash&quot;</span></span></code></pre></div><p>More providers: <a href="./guide/providers.html">Providers &amp; API keys</a>.</p></details><hr><h2 id="where-your-files-live" tabindex="-1">Where your files live <a class="header-anchor" href="#where-your-files-live" aria-label="Permalink to &quot;Where your files live&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.pagent/</span></span>
<span class="line"><span>├── pagent.toml       # your API key and model</span></span>
<span class="line"><span>├── threads/          # all conversation history</span></span>
<span class="line"><span>└── skills/           # optional local skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;your project folder&gt;/</span></span>
<span class="line"><span>└── artifacts/        # files the AI generated (HTML, etc.)</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Protect your key</p><p><code>pagent.toml</code> holds your real API key. <strong>Don&#39;t</strong> share it or commit it to Git.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Try</th></tr></thead><tbody><tr><td>&quot;Damaged, can&#39;t be opened&quot;</td><td>Run <code>xattr -cr &quot;/Applications/pagent Desktop.app&quot;</code></td></tr><tr><td>Backend / Bridge won&#39;t start</td><td>Run <code>uv tool install pagent</code>, then check the log on the right</td></tr><tr><td>Error after sending</td><td>Check the key in <code>pagent.toml</code>, or set <code>DEEPSEEK_API_KEY</code></td></tr><tr><td>Settings says &quot;no config file&quot;</td><td>Create <code>~/.pagent/pagent.toml</code> as above</td></tr><tr><td>Tool stuck on &quot;running&quot;</td><td>Tap <strong>Stop</strong>, or send another message</td></tr></tbody></table><hr><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li><strong>Connect to a remote server</strong>: the desktop app can talk to a remote <code>pagent</code> server instead of a local one (share sessions across devices). This is an advanced setup requiring transport configuration — see the repo docs.</li><li><a href="./vscode.html">VS Code extension</a> — the same AI inside VS Code, cross-platform.</li><li><a href="./guide/install.html">Install guide</a> — start here if you don&#39;t have <code>uv</code> yet.</li></ul>`,100)])])}const E=h(m,[["render",k]]);export{S as __pageData,E as default};
